#!/usr/bin/env python3
from scapy.all import sr1, IP, TCP

open_ports = []
for port in range(1, 65536):
    ans = sr1(IP(dst='127.0.0.1')/TCP(dport=port, flags='S'), timeout=0.5, verbose=0)
    if ans and ans.haslayer(TCP) and ans[TCP].flags == 0x12:
        open_ports.append(port)
        sr1(IP(dst='127.0.0.1')/TCP(dport=port, flags='R'), timeout=0.1, verbose=0)  # Clean up connection

with open('open_ports.txt', 'w') as f:
    for port in open_ports:
        f.write(f"{port}\n")
print(f"Discovered open ports: {open_ports}")

